  function contactRowsMini(){ const rows=[...(state.data.contacts||[])].sort((a,b)=>String(b.updatedAt||b.createdAt).localeCompare(String(a.updatedAt||a.createdAt))).slice(0,8); return `<div class="table-wrap"><table class="admin-table compact"><thead><tr><th>סניף</th><th>נושא</th><th>סטטוס</th><th>תגובה</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.branchName||'')}</td><td>${esc(c.subject||'')}</td><td><span class="status-pill ${c.status==='closed'?'on':'off'}">${c.status==='closed'?'✓ טופל':'פתוח'}</span></td><td>${esc(c.reply||'')}</td></tr>`).join('') || '<tr><td colspan="4">אין פניות</td></tr>'}</tbody></table></div>`; }
