    return `<div class="order-catalog-tools"><input data-filter="orderProducts" value="${esc(state.filters.orderProducts||'')}" placeholder="חיפוש מוצר / ברקוד / קטגוריה / כשרות"/><div class="category-rail admin-cat-rail"><button type="button" class="cat-chip ${selected==='all'?'active':''}" data-order-cat="all">הכל</button>${cats.map(c=>`<button type="button" class="cat-chip ${selected===c?'active':''}" data-order-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div></div><div class="order-product-grid admin-order-products">${products.map(p=>adminProductCard(p,items[p.id]||0,mode)).join('') || '<p class="empty">אין מוצרים מתאימים</p>'}</div>`;
