  renderDelivery = function(){ const rows=(state.data.deliveryExceptions||[]).map(ex=>`<tr><td>${esc(ex.mode==='cancel'?'ביטול מועד':ex.mode==='replace'?'הזזה':'הוספת מועד')}</td><td>${esc(ex.date)}</td><td>${esc(ex.mode==='replace'?ex.replacementDate:'-')}</td><td>${esc(ex.branchId?branchName(ex.branchId):(ex.networkId?networkName(ex.networkId):'כללי'))}</td><td>${esc(typeTitle(ex.deliveryTypeId)||'כל הסוגים')}</td><td>${esc(ex.reason||'')}</td><td><button class="btn sm danger" data-action="delete-exception" data-id="${ex.id}">מחיקה</button></td></tr>`).join(''); return `<section class="panel"><h2>מועדי אספקה חריגים</h2><form data-form="create-exception" class="admin-form"><div class="form-grid"><label>פעולה<select name="mode" data-exception-mode><option value="add">הוספת מועד חריג</option><option value="cancel">ביטול מועד קיים לגמרי</option><option value="replace">הזזת מועד קיים</option></select></label><label>מועד<input name="date" type="date" required/></label><label data-replacement-wrap>תאריך חלופי<input name="replacementDate" type="date"/></label><label>סוג הזמנה<select name="deliveryTypeId"><option value="">כל הסוגים</option>${activeTypes().map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><label>רשת${searchableSelect('networkId',[{value:'',label:'כל הרשתות'},...networkItems()],'','','חיפוש רשת')}</label><label>סניף${searchableSelect('branchId',[{value:'',label:'כל הסניפים'},...branchItems(state.data.branches)],'','','חיפוש סניף')}</label><label>סיבה<input name="reason"/></label></div><button class="btn primary">שמירה</button></form><div class="table-wrap"><table class="admin-table"><thead><tr><th>פעולה</th><th>מועד</th><th>חלופי</th><th>תחולה</th><th>סוג</th><th>סיבה</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7">אין חריגים</td></tr>'}</tbody></table></div></section>`; };
