  function v27BannerPanel(){ return `<section class="panel wide"><div class="panel-head"><div><h2>באנרים באפליקציה</h2><p class="muted">מופיעים במסך הראשי של האפליקציה ומתחלפים אוטומטית.</p></div></div><form data-form="create-banner" class="admin-form compact-form"><div class="form-grid"><label>כותרת<input name="title" required></label><label>טקסט<input name="text"></label><label>אייקון<input name="icon" value="📣"></label><label>תמונה / באנר<input type="file" name="imageUrl" data-image accept="image/*"></label><label>סדר<input type="number" name="sort" value="1"></label></div><label class="toggle"><input type="checkbox" name="active" data-bool checked> פעיל</label><button class="btn primary">שמירת באנר</button></form><div class="table-wrap"><table class="admin-table compact"><thead><tr><th>באנר</th><th>אייקון</th><th>סטטוס</th><th></th></tr></thead><tbody>${v27BannerRows()||'<tr><td colspan="4">אין באנרים</td></tr>'}</tbody></table></div></section>`; }
