  function v27PromoForm(){ return `<section class="panel wide"><h2>ניהול מבצעים</h2><p class="muted">הגדרת מבצע לפי רשתות, סניפים, מוצרים או קטגוריות. המבצע יוצג באפליקציה עד תאריך הסיום עם אייקון מבצע וקטגוריית מבצעים.</p><form data-form="create-promotion" class="admin-form"><div class="form-grid"><label>שם המבצע<input name="title" required placeholder="לדוגמה: 5% הנחה מעל 500 ₪"></label><label>תיאור<input name="desc"></label><label>אחוז הנחה<input type="number" name="discountPercent" min="0" max="100" step="0.1"></label><label>מינימום להזמנה / קטגוריה<input type="number" name="minValue" min="0" step="1"></label><label>מתאריך<input type="date" name="startsAt"></label><label>עד תאריך<input type="date" name="endsAt"></label></div><h3>תחולה</h3><div class="form-grid two"><label>רשתות${v27MultiList('networkIds', v27Networks())}</label><label>סניפים${v27MultiList('branchIds', v27Branches())}</label></div><h3>מוצרים וקטגוריות</h3><div class="form-grid two"><label>מוצרים${v27MultiList('productIds', v27Products())}</label><label>קטגוריות<input name="categories" placeholder="מזווה, משקאות" /></label></div><label class="toggle"><input type="checkbox" name="active" data-bool checked> פעיל</label><button class="btn primary">שמירת מבצע</button></form><h3>מבצעים קיימים</h3><div class="table-wrap"><table class="admin-table"><thead><tr><th>מבצע</th><th>רשתות/סניפים</th><th>מוצרים/קטגוריות</th><th>עד תאריך</th><th>סטטוס</th></tr></thead><tbody>${v27PromotionRows()||'<tr><td colspan="5">אין מבצעים</td></tr>'}</tbody></table></div></section>`; }
  const oldRenderIntegrationsV27 = renderIntegrations;
