  function optText(id, list, fallback=''){ return (list||[]).find(x=>x.id===id || x.value===id)?.name || (list||[]).find(x=>x.id===id || x.value===id)?.label || fallback || id || ''; }
  function money(v){ try{return fmtMoney(v)}catch{return '₪'+Number(v||0).toLocaleString('he-IL')} }
  function netLabel(id){ return optText(id, state.data?.networks, ''); }
  function brLabel(id){ const b=(state.data?.branches||[]).find(x=>x.id===id); return b ? `${b.networkName||netLabel(b.networkId)} · ${b.name||''} · ${b.city||''}` : ''; }
