    const preferred=['dashboard','orders','returns','promotions','products','networks','contacts','stats','delivery','users','integrations'];
    if(Array.isArray(screens)) screens.sort((a,b)=>{ const ia=preferred.indexOf(a[0]); const ib=preferred.indexOf(b[0]); return (ia<0?99:ia)-(ib<0?99:ib); });
