  function categoryNames(mode='current'){ let cats=[...(state.data?.categories||[])]; if(mode==='alpha') cats=cats.sort((a,b)=>String(a).localeCompare(String(b),'he')); return cats; }
  const oldTaxonomy32 = taxonomyManager;
  taxonomyManager=function(){ const cats=categoryNames(); const catRows=cats.filter(c=>contains([c],state.filters.categories)).map((c,idx)=>{ const subs=(state.data.subcategories||[]).find(r=>r.category===c)?.subcategories||[]; return `<div class="taxonomy-row category-sort-row"><div><b>${esc32(c)}</b><span>${subs.map(s=>`<em>${esc32(s)}</em>`).join('')}</span></div><div class="row-actions"><button class="btn sm ghost" data-cat-move="${esc32(c)}" data-dir="up" ${idx===0?'disabled':''}>↑</button><button class="btn sm ghost" data-cat-move="${esc32(c)}" data-dir="down" ${idx===cats.length-1?'disabled':''}>↓</button><button class="btn sm danger" data-action="delete-category" data-name="${esc32(c)}">מחיקה</button></div></div>`; }).join(''); const base=oldTaxonomy32(); return base.replace(/<div><h3>קטגוריות<\/h3>[\s\S]*?<\/div><div><h3>תתי קטגוריות<\/h3>/, `<div><h3>קטגוריות</h3><div class="category-sort-actions"><button class="btn sm ghost" data-cat-sort="alpha">מיון א-ב</button><button class="btn sm ghost" data-cat-sort="manual">שמירת סדר ידני</button></div>${filterInput('categories','חיפוש קטגוריה')}<form data-form="create-category" class="inline-form"><input name="name" placeholder="קטגוריה חדשה"/>${deliveryChecks([])}<button class="btn sm">הוסף</button></form><div class="taxonomy-list" data-category-order>${catRows}</div></div><div><h3>תתי קטגוריות</h3>`); };
